function mount(element,config){controller?.destroy();controller=null;stage=element;if(!element)return;try{controller=new Scene(element,config);}catch(e){console.warn('Cinematic canvas unavailable; keeping standard controls.',e);element.classList.remove('walk-mode');element.querySelector('.walk-canvas').hidden=true;element.querySelector('.walk-hud').hidden=true;element.querySelectorAll('.hotspot').forEach(b=>b.hidden=false);const modeButton=$('view-mode');if(modeButton){modeButton.disabled=true;modeButton.textContent='Cinematic view';}}}
